#!/usr/bin/env python3
import csv, io, json, os, sys
from datetime import datetime, timezone, timedelta
from fractions import Fraction


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    names = sorted(n for n in os.listdir(ed)
                   if n.endswith(".csv") and os.path.isfile(os.path.join(ed, n)))
    for n in names:
        with open(os.path.join(ed, n), "rb") as f:
            text = f.read().decode("utf-8-sig")
        first = text.split("\n", 1)[0]
        delim = max(",;\t", key=lambda c: first.count(c))
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for rec in rd:
            if header is None:
                header = [h.strip() for h in rec]
                continue
            cells = [c.strip() for c in rec]
            if not any(cells):
                continue
            row = {}
            for h, c in zip(header, cells):
                row[h] = c if c != "" else None
            rows.append(row)
    return rows


def parse_time(s, meta):
    if meta.get("submitted_format") == "local":
        o = meta["utc_offset"]
        sign = -1 if o[0] == "-" else 1
        off = timedelta(hours=int(o[1:3]), minutes=int(o[4:6])) * sign
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=timezone(off))
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def parse_dur(s, meta):
    if meta.get("duration_format") == "clock":
        p = [int(x) for x in s.split(":")]
        t = 0
        for x in p:
            t = t * 60 + x
        return t
    return int(s)


def median(vals):
    v = sorted(vals)
    n = len(v)
    if n % 2:
        return Fraction(v[n // 2])
    return Fraction(v[n // 2 - 1] + v[n // 2], 2)


def main(indir, outfile):
    cb = json.load(open(os.path.join(indir, "codebook.json"), encoding="utf-8"))
    wt = json.load(open(os.path.join(indir, "weighting.json"), encoding="utf-8"))
    plan = json.load(open(os.path.join(indir, "tables.json"), encoding="utf-8"))
    vkeys = list(cb["versions"].keys())
    qs = {q["id"]: q for q in cb["questions"]}
    raw = read_exports(indir)

    recs = []
    for r in raw:
        v = r.get("form_version")
        meta = cb["versions"][v]["meta"]
        rid = r.get(meta["id"])
        complete = r.get(meta["status"]) == meta["complete"]
        t = r.get(meta["submitted"])
        recs.append(dict(row=r, v=v, meta=meta, id=rid, complete=complete,
                         t=parse_time(t, meta) if t else None))
    stats = {v: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0)
             for v in vkeys}
    for x in recs:
        stats[x["v"]]["rows"] += 1

    by = {}
    for x in recs:
        by.setdefault(x["id"], []).append(x)
    kept = []
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    for rid, lst in by.items():
        best = max(lst, key=lambda x: (x["complete"], (x["t"] or epoch)))
        # first max among ties
        for x in lst:
            if x is not best:
                stats[x["v"]]["duplicates"] += 1
        kept.append(best)
    # preserve file order
    kept.sort(key=lambda x: recs.index(x)) if False else None

    k2 = []
    for x in kept:
        m = x["meta"]
        if not x["complete"]:
            lp = int(x["row"].get(m["last_page"]) or 0)
            x["last_page"] = lp
            if lp < cb["partial_min_page"]:
                stats[x["v"]]["short_partials"] += 1
                continue
        k2.append(x)
    med = {}
    for v in vkeys:
        d = [parse_dur(x["row"][x["meta"]["duration"]], x["meta"]) for x in k2
             if x["v"] == v and x["complete"]]
        med[v] = median(d) if d else None
    k3 = []
    for x in k2:
        if x["complete"]:
            d = parse_dur(x["row"][x["meta"]["duration"]], x["meta"])
            if d * 5 < med[x["v"]] * 2:
                stats[x["v"]]["speeders"] += 1
                continue
        stats[x["v"]]["complete" if x["complete"] else "partial"] += 1
        k3.append(x)
    kept = k3
    N = len(kept)

    # answers
    def conv(entry, val):
        rc = entry.get("recode")
        if rc is not None:
            return int(rc[val])
        return int(val)

    def read(q, x):
        e = q["versions"][x["v"]]
        row = x["row"]
        t = q["type"]
        if t == "multi":
            if "columns" in e:
                s = set(int(c) for c, col in e["columns"].items() if row.get(col) == "1")
            else:
                cell = row.get(e["column"])
                s = set()
                if cell:
                    for el in cell.split(e["separator"]):
                        el = el.strip()
                        if el:
                            s.add(conv(e, el))
            ex = {o["code"] for o in q["options"] if o.get("exclusive")}
            if s - ex:
                s -= ex
            elif s:
                s = set()
            miss = {o["code"] for o in q["options"] if o.get("missing")}
            s -= miss
            return s or None
        cell = row.get(e["column"])
        if cell is None:
            return None
        if t == "single":
            c = conv(e, cell)
            miss = {o["code"] for o in q["options"] if o.get("missing")}
            return None if c in miss else c
        src = e.get("source")
        if src == "band":
            return conv(e, cell)
        age = int(cell)
        if src == "birth_year":
            age = int(cb["reference_date"][:4]) - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None

    for x in kept:
        x["ans"] = {}
        x["asked"] = {}

    def asked(q, x):
        qid = q["id"]
        if qid in x["asked"]:
            return x["asked"][qid]
        x["asked"][qid] = False
        e = q["versions"].get(x["v"])
        ok = e is not None
        if ok and not x["complete"] and e["page"] > x["last_page"]:
            ok = False
        if ok and q.get("ask_if"):
            a = q["ask_if"]
            pq = qs[a["question"]]
            ok = False
            if asked(pq, x):
                ans = answer(pq, x)
                if ans is not None:
                    cs = set(a["codes"])
                    ok = bool(ans & cs) if isinstance(ans, set) else ans in cs
        x["asked"][qid] = ok
        return ok

    def answer(q, x):
        qid = q["id"]
        if qid not in x["ans"]:
            x["ans"][qid] = read(q, x) if asked(q, x) else None
        return x["ans"][qid]

    for x in kept:
        for q in cb["questions"]:
            answer(q, x)

    def codes_of(q):
        if q["type"] == "age":
            return [b["code"] for b in q["bands"]]
        return [o["code"] for o in q["options"] if not o.get("missing")]

    # weighting
    w = [1.0] * N
    dims = []
    for d in wt["dimensions"]:
        q = qs[d["question"]]
        tg = {int(k): float(v) for k, v in d["targets"].items()}
        present = {x["ans"][d["question"]] for x in kept}
        tg = {k: v for k, v in tg.items() if k in present}
        tot = sum(tg.values())
        if not tg or tot == 0:
            continue
        share = {k: v / tot for k, v in tg.items()}
        groups = {k: [i for i, x in enumerate(kept) if x["ans"][d["question"]] == k] for k in share}
        dims.append((share, groups))
    if N:
        for _ in range(wt.get("max_iterations", 100)):
            done = True
            for share, groups in dims:
                T = sum(w[i] for g in groups.values() for i in g)
                fs = {}
                for c, g in groups.items():
                    W = sum(w[i] for i in g)
                    fs[c] = share[c] * T / W if W else 1.0
                for c, g in groups.items():
                    for i in g:
                        w[i] *= fs[c]
                if any(abs(f - 1) > wt["tolerance"] for f in fs.values()):
                    done = False
            if done:
                break
        m = sum(w) / N
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(a, lo), hi) for a in w]
        m2 = sum(w) / N
        w = [a / m2 for a in w]

    # banner
    cols = [("total", None, None)]
    for bq in plan["banner"]:
        for c in codes_of(qs[bq]):
            cols.append((f"{bq}:{c}", bq, c))

    r2 = lambda v: round(v + 0.0, 2)
    tables = []
    for t in plan["tables"]:
        q = qs[t["question"]]
        opts = codes_of(q)
        multi = q["type"] == "multi"
        score = {o["code"]: o.get("score") for o in q.get("options", [])}
        outc = []
        base_idx = [i for i, x in enumerate(kept) if x["ans"][q["id"]] is not None]
        for cid, bq, bc in cols:
            idx = [i for i in base_idx if bq is None or kept[i]["ans"][bq] == bc]
            wb = sum(w[i] for i in idx)
            vals = {}
            if not idx:
                for c in opts:
                    vals[str(c)] = None
                for n in t.get("nets", []):
                    vals[n["id"]] = None
                if t.get("mean"):
                    vals["mean"] = None
                outc.append(dict(column=cid, base=0, weighted_base=0, values=vals))
                continue

            def has(i, cs):
                a = kept[i]["ans"][q["id"]]
                return bool(a & set(cs)) if multi else a in cs
            for c in opts:
                vals[str(c)] = r2(100 * sum(w[i] for i in idx if has(i, [c])) / wb)
            for n in t.get("nets", []):
                vals[n["id"]] = r2(100 * sum(w[i] for i in idx if has(i, n["codes"])) / wb)
            if t.get("mean"):
                vals["mean"] = r2(sum(w[i] * score[kept[i]["ans"][q["id"]]] for i in idx) / wb)
            outc.append(dict(column=cid, base=len(idx), weighted_base=r2(wb), values=vals))
        tables.append(dict(table=t["id"], columns=outc))

    summ = dict(
        versions=[dict(version=v, **stats[v]) for v in vkeys],
        respondents=N,
        effective_n=r2(sum(w) ** 2 / sum(a * a for a in w)) if N else None,
        weight_min=r2(min(w)) if N else None,
        weight_max=r2(max(w)) if N else None)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(dict(survey=cb["survey"], summary=summ, tables=tables), f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
